// comments.go - 댓글 시스템
// GetComments, CreateComment 구현

package api

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

// ==================== 데이터 모델 ====================

type Comment struct {
	ID        string    `json:"id"`
	SnippetID string    `json:"snippet_id"`
	UserID    string    `json:"user_id"`
	Username  string    `json:"username"`
	Content   string    `json:"content"`
	CreatedAt time.Time `json:"created_at"`
}

type CreateCommentRequest struct {
	Content string `json:"content"`
}

// ==================== 테이블 초기화 ====================

func InitCommentsTable(db *sql.DB) error {
	schema := `
	CREATE TABLE IF NOT EXISTS comments (
		id TEXT PRIMARY KEY,
		snippet_id TEXT NOT NULL,
		user_id TEXT NOT NULL,
		username TEXT NOT NULL,
		content TEXT NOT NULL,
		created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
		FOREIGN KEY (snippet_id) REFERENCES snippets(id) ON DELETE CASCADE
	);

	CREATE INDEX IF NOT EXISTS idx_comments_snippet_id ON comments(snippet_id);
	`

	_, err := db.Exec(schema)
	return err
}

// ==================== HTTP 핸들러 ====================

// GET /api/v2/snippets/{id}/comments
// 인증 불필요 (공개 조회)
func GetComments(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		snippetID := r.PathValue("id")
		if snippetID == "" {
			WriteError(w, http.StatusBadRequest, "Snippet ID required")
			return
		}

		// 댓글 목록 조회 (생성일 오름차순)
		rows, err := db.Query(`
			SELECT id, snippet_id, user_id, username, content, created_at
			FROM comments
			WHERE snippet_id = ?
			ORDER BY created_at ASC
		`, snippetID)

		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Database query failed")
			return
		}
		defer rows.Close()

		comments := []Comment{}
		for rows.Next() {
			var c Comment
			if err := rows.Scan(&c.ID, &c.SnippetID, &c.UserID, &c.Username, &c.Content, &c.CreatedAt); err != nil {
				continue
			}
			comments = append(comments, c)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    comments,
			"count":   len(comments),
		})
	}
}

// POST /api/v2/snippets/{id}/comments
// 인증 필요 (JWT)
func CreateComment(db *sql.DB, jwtSecret string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Context에서 user_id, username 추출 (AuthMiddleware가 설정)
		userID, ok := r.Context().Value("user_id").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated")
			return
		}

		username, ok := r.Context().Value("username").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated")
			return
		}

		snippetID := r.PathValue("id")
		if snippetID == "" {
			WriteError(w, http.StatusBadRequest, "Snippet ID required")
			return
		}

		// 요청 바디 파싱
		var req CreateCommentRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			WriteError(w, http.StatusBadRequest, "Invalid request body")
			return
		}

		// 검증
		if req.Content == "" {
			WriteError(w, http.StatusBadRequest, "Comment content required")
			return
		}

		if len(req.Content) > 1000 {
			WriteError(w, http.StatusBadRequest, "Comment too long (max 1000 chars)")
			return
		}

		// 스니펫 존재 확인
		var existingID string
		err := db.QueryRow("SELECT id FROM snippets WHERE id = ?", snippetID).Scan(&existingID)
		if err == sql.ErrNoRows {
			WriteError(w, http.StatusNotFound, "Snippet not found")
			return
		}
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Database error")
			return
		}

		// 댓글 생성
		commentID := generateID("comment")
		now := time.Now().UTC()

		_, err = db.Exec(`
			INSERT INTO comments (id, snippet_id, user_id, username, content, created_at)
			VALUES (?, ?, ?, ?, ?, ?)
		`, commentID, snippetID, userID, username, req.Content, now)

		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Failed to create comment")
			return
		}

		comment := Comment{
			ID:        commentID,
			SnippetID: snippetID,
			UserID:    userID,
			Username:  username,
			Content:   req.Content,
			CreatedAt: now,
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    comment,
		})
	}
}

