// notifications_screen.dart - 알림 화면
// JWT 인증된 사용자의 알림 목록 표시

import 'package:flutter/material.dart';
import '../services/hub_api_client.dart';
import 'package:intl/intl.dart';

class NotificationsScreen extends StatefulWidget {
  const NotificationsScreen({Key? key}) : super(key: key);

  @override
  State<NotificationsScreen> createState() => _NotificationsScreenState();
}

class _NotificationsScreenState extends State<NotificationsScreen> {
  final HubApiClient _apiClient = HubApiClient();

  List<NotificationResponse> _notifications = [];
  bool _isLoading = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    _loadNotifications();
  }

  Future<void> _loadNotifications() async {
    if (_isLoading) return;

    setState(() {
      _isLoading = true;
      _error = null;
    });

    try {
      await _apiClient.initialize();
      final notifications = await _apiClient.getNotifications();

      setState(() {
        _notifications = notifications;
      });
    } catch (e) {
      setState(() {
        _error = e.toString();
      });
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

  Future<void> _markAsRead(String notificationID) async {
    try {
      await _apiClient.markNotificationRead(notificationID);
      // UI 즉시 갱신
      setState(() {
        final index = _notifications.indexWhere((n) => n.id == notificationID);
        if (index >= 0) {
          _notifications[index] = NotificationResponse(
            id: _notifications[index].id,
            userID: _notifications[index].userID,
            type: _notifications[index].type,
            actorUsername: _notifications[index].actorUsername,
            snippetID: _notifications[index].snippetID,
            snippetTitle: _notifications[index].snippetTitle,
            isRead: true,
            createdAt: _notifications[index].createdAt,
          );
        }
      });
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('오류: $e')),
      );
    }
  }

  Future<void> _markAllAsRead() async {
    try {
      await _apiClient.markAllNotificationsRead();
      setState(() {
        for (int i = 0; i < _notifications.length; i++) {
          _notifications[i] = NotificationResponse(
            id: _notifications[i].id,
            userID: _notifications[i].userID,
            type: _notifications[i].type,
            actorUsername: _notifications[i].actorUsername,
            snippetID: _notifications[i].snippetID,
            snippetTitle: _notifications[i].snippetTitle,
            isRead: true,
            createdAt: _notifications[i].createdAt,
          );
        }
      });
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('오류: $e')),
      );
    }
  }

  String _getRelativeTime(DateTime dateTime) {
    final now = DateTime.now();
    final difference = now.difference(dateTime);

    if (difference.inMinutes < 1) {
      return '방금 전';
    } else if (difference.inHours < 1) {
      return '${difference.inMinutes}분 전';
    } else if (difference.inDays < 1) {
      return '${difference.inHours}시간 전';
    } else if (difference.inDays < 7) {
      return '${difference.inDays}일 전';
    } else {
      return DateFormat('MM월 dd일').format(dateTime);
    }
  }

  IconData _getNotificationIcon(String type) {
    return type == 'comment' ? Icons.chat_bubble : Icons.favorite;
  }

  Color _getNotificationColor(String type) {
    return type == 'comment' ? Colors.blue : Colors.red;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('알림'),
        actions: [
          if (_notifications.isNotEmpty)
            TextButton(
              onPressed: _markAllAsRead,
              child: const Text('모두 읽음'),
            ),
        ],
      ),
      body: _buildBody(),
    );
  }

  Widget _buildBody() {
    if (_isLoading) {
      return const Center(
        child: CircularProgressIndicator(),
      );
    }

    if (_error != null) {
      return Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(Icons.error_outline, size: 48, color: Colors.red[300]),
            const SizedBox(height: 12),
            Text(
