import 'package:dio/dio.dart';

// ==================== 데이터 모델 ====================

class SnippetResponse {
  final String id;
  final String title;
  final String code;
  final String author;
  final List<String> tags;
  final int likes;
  final String createdAt;

  SnippetResponse({
    required this.id,
    required this.title,
    required this.code,
    required this.author,
    required this.tags,
    required this.likes,
    required this.createdAt,
  });

  factory SnippetResponse.fromJson(Map<String, dynamic> json) {
    return SnippetResponse(
      id: json['id'] as String? ?? '',
      title: json['title'] as String? ?? '',
      code: json['code'] as String? ?? '',
      author: json['author'] as String? ?? '',
      tags: List<String>.from(json['tags'] as List? ?? []),
      likes: json['likes'] as int? ?? 0,
      createdAt: json['created_at'] as String? ?? '',
    );
  }

  Map<String, dynamic> toJson() => {
        'id': id,
        'title': title,
        'code': code,
        'author': author,
        'tags': tags,
        'likes': likes,
        'created_at': createdAt,
      };
}

class TutorialResponse {
  final int id;
  final String title;
  final String description;
  final int totalSteps;
  final int difficulty;
  final List<String> steps;

  TutorialResponse({
    required this.id,
    required this.title,
    required this.description,
    required this.totalSteps,
    required this.difficulty,
    required this.steps,
  });

  factory TutorialResponse.fromJson(Map<String, dynamic> json) {
    return TutorialResponse(
      id: json['id'] as int? ?? 0,
      title: json['title'] as String? ?? '',
      description: json['description'] as String? ?? '',
      totalSteps: json['total_steps'] as int? ?? 0,
      difficulty: json['difficulty'] as int? ?? 1,
      steps: List<String>.from(json['steps'] as List? ?? []),
    );
  }
}

class LeaderboardEntryResponse {
  final int rank;
  final String username;
  final int score;
  final int contributions;

  LeaderboardEntryResponse({
    required this.rank,
    required this.username,
    required this.score,
    required this.contributions,
  });

  factory LeaderboardEntryResponse.fromJson(Map<String, dynamic> json) {
    return LeaderboardEntryResponse(
      rank: json['rank'] as int? ?? 0,
      username: json['username'] as String? ?? '',
      score: json['score'] as int? ?? 0,
      contributions: json['contributions'] as int? ?? 0,
    );
  }
}

class ApiException implements Exception {
  final String message;
  final int? statusCode;
  final dynamic originalError;

  ApiException({
    required this.message,
    this.statusCode,
    this.originalError,
  });

  @override
  String toString() =>
      'ApiException: $message${statusCode != null ? ' (HTTP $statusCode)' : ''}';
}

// ==================== API 클라이언트 ====================

class HubApiClient {
  static final HubApiClient _instance = HubApiClient._internal();

  factory HubApiClient({String baseUrl = 'http://localhost:3000/api/v2'}) {
    _instance._baseUrl = baseUrl;
    return _instance;
  }

  HubApiClient._internal();

  late String _baseUrl;
  late Dio _dio;
  bool _initialized = false;

  Future<void> initialize() async {
    if (_initialized) return;

    _dio = Dio(
      BaseOptions(
        baseUrl: _baseUrl,
        connectTimeout: const Duration(seconds: 10),
        receiveTimeout: const Duration(seconds: 10),
        sendTimeout: const Duration(seconds: 10),
        contentType: 'application/json',
      ),
    );

    // 요청 로깅 인터셉터
    _dio.interceptors.add(
      LoggingInterceptor(),
    );

    // 에러 처리 인터셉터
    _dio.interceptors.add(
      ErrorInterceptor(),
    );

    _initialized = true;
  }

  // ==================== 스니펫 API ====================

  /// 스니펫 목록 조회 (페이징 & 필터)
  /// [page]: 1부터 시작
  /// [limit]: 페이지당 아이템 수
  /// [tag]: 필터링 태그 (선택사항)
  Future<List<SnippetResponse>> getSnippets({
    int page = 1,
    int limit = 10,
    String? tag,
  }) async {
    try {
      final response = await _dio.get<Map<String, dynamic>>(
        '/snippets',
        queryParameters: {
          'page': page,
          'limit': limit,
          if (tag != null) 'tag': tag,
        },
      );

      final data = response.data?['data'] as List? ?? [];
      return data
          .map((item) => SnippetResponse.fromJson(item as Map<String, dynamic>))
          .toList();
    } on DioException catch (e) {
      throw ApiException(
        message: '스니펫 조회 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  /// 스니펫 검색
  Future<List<SnippetResponse>> searchSnippets(String query) async {
    try {
      final response = await _dio.get<Map<String, dynamic>>(
        '/snippets/search',
        queryParameters: {'q': query},
      );

      final data = response.data?['data'] as List? ?? [];
      return data
          .map((item) => SnippetResponse.fromJson(item as Map<String, dynamic>))
          .toList();
    } on DioException catch (e) {
      throw ApiException(
        message: '검색 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  /// 추천 스니펫 (좋아요 순)
  Future<List<SnippetResponse>> getRecommendations({int limit = 10}) async {
    try {
      final response = await _dio.get<Map<String, dynamic>>(
        '/recommendations',
        queryParameters: {'limit': limit},
      );

      final data = response.data?['data'] as List? ?? [];
      return data
          .map((item) => SnippetResponse.fromJson(item as Map<String, dynamic>))
          .toList();
    } on DioException catch (e) {
      throw ApiException(
        message: '추천 조회 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  /// 스니펫 단건 조회
  Future<SnippetResponse> getSnippet(String id) async {
    try {
      final response = await _dio.get<Map<String, dynamic>>('/snippets/$id');
      return SnippetResponse.fromJson(
        response.data?['data'] as Map<String, dynamic>? ?? {},
      );
    } on DioException catch (e) {
      throw ApiException(
        message: '스니펫 조회 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  /// 스니펫 업로드
  Future<SnippetResponse> createSnippet({
    required String title,
    required String code,
    required List<String> tags,
  }) async {
    try {
      final response = await _dio.post<Map<String, dynamic>>(
        '/snippets',
        data: {
          'title': title,
          'code': code,
          'tags': tags,
        },
      );

      return SnippetResponse.fromJson(
        response.data?['data'] as Map<String, dynamic>? ?? {},
      );
    } on DioException catch (e) {
      throw ApiException(
        message: '스니펫 업로드 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  /// 스니펫 좋아요
  Future<void> likeSnippet(String snippetId) async {
    try {
      await _dio.post('/snippets/$snippetId/like');
    } on DioException catch (e) {
      throw ApiException(
        message: '좋아요 반영 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  /// 스니펫 좋아요 취소
  Future<void> unlikeSnippet(String snippetId) async {
    try {
      await _dio.delete('/snippets/$snippetId/like');
    } on DioException catch (e) {
      throw ApiException(
        message: '좋아요 취소 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  // ==================== 튜토리얼 API ====================

  /// 튜토리얼 목록
  Future<List<TutorialResponse>> getTutorials() async {
    try {
      final response = await _dio.get<Map<String, dynamic>>('/tutorials');
      final data = response.data?['data'] as List? ?? [];
      return data
          .map((item) =>
              TutorialResponse.fromJson(item as Map<String, dynamic>))
          .toList();
    } on DioException catch (e) {
      throw ApiException(
        message: '튜토리얼 조회 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  /// 튜토리얼 단건 조회
  Future<TutorialResponse> getTutorial(int id) async {
    try {
      final response = await _dio.get<Map<String, dynamic>>('/tutorials/$id');
      return TutorialResponse.fromJson(
        response.data?['data'] as Map<String, dynamic>? ?? {},
      );
    } on DioException catch (e) {
      throw ApiException(
        message: '튜토리얼 조회 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  // ==================== 리더보드 API ====================

  /// 리더보드 조회
  /// [period]: 'weekly', 'monthly', 'alltime'
  Future<List<LeaderboardEntryResponse>> getLeaderboard({
    String period = 'weekly',
  }) async {
    try {
      final response = await _dio.get<Map<String, dynamic>>(
        '/leaderboard',
        queryParameters: {'period': period},
      );

      final data = response.data?['data'] as List? ?? [];
      return data
          .map((item) => LeaderboardEntryResponse.fromJson(
              item as Map<String, dynamic>))
          .toList();
    } on DioException catch (e) {
      throw ApiException(
        message: '리더보드 조회 실패',
        statusCode: e.response?.statusCode,
        originalError: e,
      );
    }
  }

  // ==================== 헬스체크 ====================

  /// API 서버 상태 확인
  Future<bool> healthCheck() async {
    try {
      final response = await _dio.get<Map<String, dynamic>>(
        '/health',
        options: Options(
          receiveTimeout: const Duration(seconds: 3),
        ),
      );
      return response.statusCode == 200;
    } catch (e) {
      return false;
    }
  }
}

// ==================== 인터셉터 ====================

class LoggingInterceptor extends Interceptor {
  @override
  void onRequest(RequestOptions options, RequestInterceptorHandler handler) {
    print('[API] ${options.method} ${options.path}');
    handler.next(options);
  }

  @override
  void onResponse(Response response, ResponseInterceptorHandler handler) {
    print('[API] ✓ ${response.statusCode} ${response.requestOptions.path}');
    handler.next(response);
  }

  @override
  void onError(DioException err, ErrorInterceptorHandler handler) {
    print('[API] ✗ ${err.response?.statusCode} - ${err.message}');
    handler.next(err);
  }
}

class ErrorInterceptor extends Interceptor {
  @override
  void onError(DioException err, ErrorInterceptorHandler handler) {
    if (err.response?.statusCode == 401) {
      // 미인증 - 로그인 재필요
      print('[API] 인증 만료');
    } else if (err.response?.statusCode == 429) {
      // Rate limit
      print('[API] 요청 제한 초과');
    } else if (err.type == DioExceptionType.connectionTimeout ||
        err.type == DioExceptionType.receiveTimeout) {
      print('[API] 타임아웃');
    }
    handler.next(err);
  }
}

