// game_ast.dart - FreeLang Game DSL 추상 구문 트리 (중급)
// 구조: 장면(Scene) → 스프라이트(Sprite) → 이벤트(Event) → 액션(Action)

// ==================== 기본 타입 ====================

class Position {
  final double x;
  final double y;

  Position(this.x, this.y);

  Position operator +(Position other) => Position(x + other.x, y + other.y);
  Position operator -(Position other) => Position(x - other.x, y - other.y);

  double distance(Position other) {
    final dx = x - other.x;
    final dy = y - other.y;
    return (dx * dx + dy * dy).sqrt();
  }

  @override
  String toString() => 'Position($x, $y)';
}

class Size {
  final double width;
  final double height;

  Size(this.width, this.height);

  @override
  String toString() => 'Size($width, $height)';
}

class Color {
  final int r;
  final int g;
  final int b;
  final int a;

  Color({required this.r, required this.g, required this.b, this.a = 255});

  factory Color.fromHex(String hex) {
    // #RRGGBB 또는 #RRGGBBAA
    final value = int.parse(hex.replaceFirst('#', ''), radix: 16);
    if (hex.length == 7) {
      return Color(
        r: (value >> 16) & 0xFF,
        g: (value >> 8) & 0xFF,
        b: value & 0xFF,
      );
    } else {
      return Color(
        r: (value >> 24) & 0xFF,
        g: (value >> 16) & 0xFF,
        b: (value >> 8) & 0xFF,
        a: value & 0xFF,
      );
    }
  }

  @override
  String toString() => 'Color($r,$g,$b,$a)';
}

// ==================== 장면 (Scene) ====================

abstract class GameElement {
  String get id;
  Position get position;
  Set<String> get dependencies; // 다른 엘리먼트 참조
}

class Sprite implements GameElement {
  @override
  final String id;

  @override
  final Position position;

  final Size size;
  final String? image; // 이미지 파일 경로
  final Color? backgroundColor;
  final List<Animation> animations;
  final double speed;
  final double rotation;
  final List<EventHandler> eventHandlers;

  Sprite({
    required this.id,
    required this.position,
    required this.size,
    this.image,
    this.backgroundColor,
    this.animations = const [],
    this.speed = 5.0,
    this.rotation = 0.0,
    this.eventHandlers = const [],
  });

  @override
  Set<String> get dependencies {
    return eventHandlers
        .where((e) => e.action is CallAction)
        .map((e) => (e.action as CallAction).targetId)
        .toSet();
  }

  Sprite copyWith({
    Position? position,
    Size? size,
    String? image,
    Color? backgroundColor,
    List<Animation>? animations,
    double? speed,
    double? rotation,
    List<EventHandler>? eventHandlers,
  }) {
    return Sprite(
      id: id,
      position: position ?? this.position,
      size: size ?? this.size,
      image: image ?? this.image,
      backgroundColor: backgroundColor ?? this.backgroundColor,
      animations: animations ?? this.animations,
      speed: speed ?? this.speed,
      rotation: rotation ?? this.rotation,
      eventHandlers: eventHandlers ?? this.eventHandlers,
    );
  }

  @override
  String toString() => 'Sprite($id at $position)';
}

// ==================== 애니메이션 ====================

class Animation {
  final String name;
  final List<Frame> frames;
  final int duration; // 밀리초
  final bool loop;

  Animation({
    required this.name,
    required this.frames,
    required this.duration,
    this.loop = true,
  });

  int get frameDuration => duration ~/ frames.length;

  @override
  String toString() => 'Animation($name, ${frames.length} frames)';
}

class Frame {
  final String imageRegion; // "image.png:0,0,32,32"
  final int? duration; // 밀리초 (없으면 기본값 사용)

  Frame({required this.imageRegion, this.duration});
}

// ==================== 이벤트 & 액션 ====================

enum EventType {
  touch, // 터치
  collision, // 충돌
  update, // 매 프레임
  timer, // 타이머
  custom, // 커스텀
}

class EventHandler {
  final EventType type;
  final String? condition; // 조건식 (예: "x > 300")
  final GameAction action;

  EventHandler({
    required this.type,
    this.condition,
    required this.action,
  });

  @override
  String toString() => 'EventHandler($type)';
}

abstract class GameAction {
  void execute(GameRuntime runtime);
}

class MoveAction extends GameAction {
  final String spriteId;
  final Position target;
  final int duration; // 밀리초

  MoveAction({
    required this.spriteId,
    required this.target,
    required this.duration,
  });

  @override
  void execute(GameRuntime runtime) {
    final sprite = runtime.getSprite(spriteId);
    if (sprite != null) {
      runtime.animateSprite(spriteId, sprite.position, target, duration);
    }
  }

  @override
  String toString() => 'MoveAction($spriteId → $target in ${duration}ms)';
}

class RotateAction extends GameAction {
  final String spriteId;
  final double angle;
  final int duration;

  RotateAction({
    required this.spriteId,
    required this.angle,
    required this.duration,
  });

  @override
  void execute(GameRuntime runtime) {
    // TODO: 로테이션 애니메이션
  }

  @override
  String toString() => 'RotateAction($spriteId → ${angle}° in ${duration}ms)';
}

class ShowTextAction extends GameAction {
  final String text;
  final Position position;
  final Color color;
  final int fontSize;

  ShowTextAction({
    required this.text,
    required this.position,
    required this.color,
    required this.fontSize,
  });

  @override
  void execute(GameRuntime runtime) {
    runtime.showText(text, position, color, fontSize);
  }

  @override
  String toString() => 'ShowTextAction("$text" at $position)';
}

class SceneChangeAction extends GameAction {
  final String nextSceneId;

  SceneChangeAction({required this.nextSceneId});

  @override
  void execute(GameRuntime runtime) {
    runtime.changeScene(nextSceneId);
  }

  @override
  String toString() => 'SceneChangeAction($nextSceneId)';
}

class CallAction extends GameAction {
  final String targetId;
  final String methodName;
  final List<String> args;

  CallAction({
    required this.targetId,
    required this.methodName,
    required this.args,
  });

  @override
  void execute(GameRuntime runtime) {
    // TODO: 메서드 호출
  }

  @override
  String toString() => 'CallAction($targetId.$methodName)';
}

class SequenceAction extends GameAction {
  final List<GameAction> actions;

  SequenceAction({required this.actions});

  @override
  void execute(GameRuntime runtime) {
    for (final action in actions) {
      action.execute(runtime);
    }
  }

  @override
  String toString() => 'SequenceAction(${actions.length} actions)';
}

class ParallelAction extends GameAction {
  final List<GameAction> actions;

  ParallelAction({required this.actions});

  @override
  void execute(GameRuntime runtime) {
    for (final action in actions) {
      action.execute(runtime);
    }
  }

  @override
  String toString() => 'ParallelAction(${actions.length} actions)';
}

// ==================== 장면 (Scene) ====================

class Scene {
  final String id;
  final String title;
  final Map<String, Sprite> sprites;
  final Color backgroundColor;
  final List<EventHandler> globalEvents;

  Scene({
    required this.id,
    required this.title,
    required this.sprites,
    required this.backgroundColor,
    this.globalEvents = const [],
  });

  Sprite? getSprite(String id) => sprites[id];

  List<Sprite> get spriteList => sprites.values.toList();

  @override
  String toString() => 'Scene($id: $title, ${sprites.length} sprites)';
}

// ==================== 게임 (Game) ====================

class Game {
  final String id;
  final String title;
  final Size screenSize;
  final Map<String, Scene> scenes;
  final String startSceneId;

  Game({
    required this.id,
    required this.title,
    required this.screenSize,
    required this.scenes,
    required this.startSceneId,
  });

  Scene? getScene(String id) => scenes[id];

  Scene? get startScene => scenes[startSceneId];

  List<Scene> get sceneList => scenes.values.toList();

  @override
  String toString() => 'Game($id: $title, ${scenes.length} scenes)';
}

// ==================== 런타임 ====================

abstract class GameRuntime {
  Sprite? getSprite(String id);
  void animateSprite(String id, Position from, Position to, int duration);
  void showText(String text, Position position, Color color, int fontSize);
  void changeScene(String sceneId);
  void playSound(String soundId);
}

