// flame_game_runtime.dart - Flame 기반 게임 런타임
// Game AST → Flame 엔진 변환 및 실행

import 'package:flame/game.dart';
import 'package:flame/components.dart';
import 'package:flame/input.dart';
import 'package:flutter/material.dart' as m;
import '../dsl/game_ast.dart';

// ==================== 게임 런타임 구현 ====================

class FlameGameRuntime extends Game with HasGameRef, MultiTouchDragDetector {
  final Game gameAST;
  final Function(int score)? onScoreChanged;
  final Function()? onGameOver;
  final Function()? onGameWin;

  late Scene currentScene;
  final Map<String, GameSpriteComponent> spriteComponents = {};
  final List<TextComponent> textComponents = [];

  int score = 0;
  bool isGameOver = false;
  bool isWon = false;

  FlameGameRuntime({
    required this.gameAST,
    this.onScoreChanged,
    this.onGameOver,
    this.onGameWin,
  });

  @override
  Future<void> onLoad() async {
    await super.onLoad();

    // 카메라 설정
    camera.viewfinder.position = Vector2(
      gameAST.screenSize.width / 2,
      gameAST.screenSize.height / 2,
    );

    // 시작 장면 로드
    await loadScene(gameAST.startSceneId);
  }

  // ==================== 장면 관리 ====================

  Future<void> loadScene(String sceneId) async {
    final scene = gameAST.getScene(sceneId);
    if (scene == null) return;

    currentScene = scene;

    // 기존 컴포넌트 제거
    for (final component in spriteComponents.values) {
      remove(component);
    }
    spriteComponents.clear();

    for (final text in textComponents) {
      remove(text);
    }
    textComponents.clear();

    // 배경색 설정
    final bgColor = scene.backgroundColor;
    world.children.whereType<ColoredBackground>().forEach((c) => c.removeFromParent());
    add(ColoredBackground(
      color: m.Color.fromARGB(bgColor.a, bgColor.r, bgColor.g, bgColor.b),
    ));

    // 스프라이트 로드
    for (final sprite in scene.spriteList) {
      await addSpriteToScene(sprite);
    }

    // 글로벌 이벤트 등록
    for (final event in scene.globalEvents) {
      registerEventHandler(event);
    }
  }

  Future<void> addSpriteToScene(Sprite spriteAST) async {
    final component = GameSpriteComponent(
      spriteAST: spriteAST,
      runtime: this,
    );
    spriteComponents[spriteAST.id] = component;
    add(component);
  }

  // ==================== 이벤트 처리 ====================

  void registerEventHandler(EventHandler event) {
    switch (event.type) {
      case EventType.update:
        // Update는 매프레임 processComponent에서 처리
        break;
      case EventType.touch:
        // Touch는 onDragStart/onDragEnd에서 처리
        break;
      case EventType.collision:
        // Collision은 계산으로 처리
        break;
      case EventType.timer:
        // Timer는 별도로 처리
        break;
      case EventType.custom:
        break;
    }
  }

  @override
  void update(double dt) {
    super.update(dt);

    // 프레임별 이벤트 처리
    for (final sprite in currentScene.spriteList) {
      for (final eventHandler in sprite.eventHandlers) {
        if (eventHandler.type == EventType.update) {
          eventHandler.action.execute(GameRuntimeAdapter(this));
        }
      }
    }

    // 글로벌 이벤트
    for (final eventHandler in currentScene.globalEvents) {
      if (eventHandler.type == EventType.update) {
        eventHandler.action.execute(GameRuntimeAdapter(this));
      }
    }
  }

  @override
  void onDragStart(DragStartInfo info) {
    super.onDragStart(info);

    final pos = info.localPosition;

    // 터치 영역의 스프라이트 찾기
    for (final sprite in currentScene.spriteList) {
      final component = spriteComponents[sprite.id];
      if (component == null) continue;

      final spriteRect = Rect.fromLTWH(
        sprite.position.x - sprite.size.width / 2,
        sprite.position.y - sprite.size.height / 2,
        sprite.size.width,
        sprite.size.height,
      );

      if (spriteRect.contains(Offset(pos.x, pos.y))) {
        // 스프라이트 터치 이벤트
        for (final eventHandler in sprite.eventHandlers) {
          if (eventHandler.type == EventType.touch) {
            eventHandler.action.execute(GameRuntimeAdapter(this));
          }
        }
      }
    }

    // 글로벌 터치 이벤트
    for (final eventHandler in currentScene.globalEvents) {
      if (eventHandler.type == EventType.touch) {
        eventHandler.action.execute(GameRuntimeAdapter(this));
      }
    }
  }

  // ==================== 스프라이트 접근 ====================

  Sprite? getSprite(String id) {
    return currentScene.getSprite(id);
  }

  GameSpriteComponent? getSpriteComponent(String id) {
    return spriteComponents[id];
  }

  // ==================== 액션 실행 ====================

  void animateSprite(
    String spriteId,
    Position from,
    Position to,
    int duration,
  ) {
    final component = spriteComponents[spriteId];
    if (component == null) return;

    final durationSeconds = duration / 1000.0;
    component.position = Vector2(from.x, from.y);

    component.add(
      MoveTo(
        Vector2(to.x, to.y),
        duration: durationSeconds,
      ),
    );
  }

  void showText(
    String text,
    Position position,
    Color color,
    int fontSize,
  ) {
    final textComponent = TextComponent(
      text: text,
      position: Vector2(position.x, position.y),
      textRenderer: TextPaint(
        style: m.TextStyle(
          color: m.Color.fromARGB(color.a, color.r, color.g, color.b),
          fontSize: fontSize.toDouble(),
        ),
      ),
    );
    textComponents.add(textComponent);
    add(textComponent);
  }

  void changeScene(String sceneId) {
    loadScene(sceneId);
  }

  void playSound(String soundId) {
    // TODO: 음성 재생
  }

  // ==================== 게임 상태 ====================

  void setScore(int newScore) {
    score = newScore;
    onScoreChanged?.call(score);
  }

  void addScore(int points) {
    setScore(score + points);
  }

  void endGame() {
    isGameOver = true;
    onGameOver?.call();
  }

  void winGame() {
    isWon = true;
    onGameWin?.call();
  }

  @override
  Future<void> onRemove() async {
    spriteComponents.clear();
    textComponents.clear();
    super.onRemove();
  }
}

// ==================== 스프라이트 컴포넌트 ====================

class GameSpriteComponent extends PositionComponent with Tappable {
  final Sprite spriteAST;
  final FlameGameRuntime runtime;

  GameSpriteComponent({
    required this.spriteAST,
    required this.runtime,
  }) : super(
    position: Vector2(spriteAST.position.x, spriteAST.position.y),
    size: Vector2(spriteAST.size.width, spriteAST.size.height),
    anchor: Anchor.center,
  );

  @override
  Future<void> onLoad() async {
    await super.onLoad();

    // 배경색 설정
    if (spriteAST.backgroundColor != null) {
      final bgColor = spriteAST.backgroundColor!;
      add(
        RectangleComponent(
          size: size,
          paint: m.Paint()
            ..color = m.Color.fromARGB(bgColor.a, bgColor.r, bgColor.g, bgColor.b),
        ),
      );
    }

    // 이미지 설정
    if (spriteAST.image != null) {
      try {
        final sprite = await Sprite.load(spriteAST.image!);
        add(SpriteComponent(sprite: sprite, size: size));
      } catch (e) {
        // 이미지 로드 실패 시 색상 사각형으로 대체
        final paint = m.Paint()
          ..color = m.Colors.grey;
        add(RectangleComponent(size: size, paint: paint));
      }
    } else {
      // 기본: 색상 사각형
      final paint = m.Paint()
        ..color = m.Colors.blue;
      add(RectangleComponent(size: size, paint: paint));
    }
  }

  @override
  bool onTapDown(TapDownInfo info) {
    // 스프라이트 터치 이벤트 처리
    for (final eventHandler in spriteAST.eventHandlers) {
      if (eventHandler.type == EventType.touch) {
        eventHandler.action.execute(GameRuntimeAdapter(runtime));
      }
    }
    return super.onTapDown(info);
  }

  void updatePosition(Position newPos) {
    position = Vector2(newPos.x, newPos.y);
  }
}

// ==================== 배경색 컴포넌트 ====================

class ColoredBackground extends Component {
  final m.Color color;

  ColoredBackground({required this.color});

  @override
  void render(Canvas canvas) {
    canvas.drawRect(
      Rect.fromLTWH(0, 0, 800, 600),
      m.Paint()..color = color,
    );
  }
}

// ==================== GameRuntime 어댑터 ====================

class GameRuntimeAdapter extends GameRuntime {
  final FlameGameRuntime flameRuntime;

  GameRuntimeAdapter(this.flameRuntime);

  @override
  Sprite? getSprite(String id) {
    return flameRuntime.getSprite(id);
  }

  @override
  void animateSprite(String id, Position from, Position to, int duration) {
    flameRuntime.animateSprite(id, from, to, duration);
  }

  @override
  void showText(String text, Position position, Color color, int fontSize) {
    flameRuntime.showText(text, position, color, fontSize);
  }

  @override
  void changeScene(String sceneId) {
    flameRuntime.changeScene(sceneId);
  }

  @override
  void playSound(String soundId) {
    flameRuntime.playSound(soundId);
  }
}

