import '../dsl/game_ast.dart';

// ==================== FlappyBird 게임 정의 ====================

Game createFlappyBirdGame() {
  const screenWidth = 800.0;
  const screenHeight = 600.0;

  // 플레이어 스프라이트 (새)
  final player = Sprite(
    id: 'player',
    position: Position(100, 300),
    size: Size(40, 40),
    backgroundColor: Color(r: 255, g: 200, b: 0), // 황색
    speed: 5.0,
    eventHandlers: [
      // 프레임마다 중력 적용
      EventHandler(
        type: EventType.update,
        action: GravityAction(spriteId: 'player', gravity: 500),
      ),
      // 터치하면 점프
      EventHandler(
        type: EventType.touch,
        action: JumpAction(spriteId: 'player', jumpForce: -400),
      ),
    ],
  );

  // 파이프 생성 (상단)
  final pipeTop = Sprite(
    id: 'pipe_top',
    position: Position(screenWidth, 150),
    size: Size(80, 200),
    backgroundColor: Color(r: 0, g: 150, b: 0), // 녹색
    eventHandlers: [
      // 파이프 이동
      EventHandler(
        type: EventType.update,
        action: ScrollAction(spriteId: 'pipe_top', speed: -200),
      ),
    ],
  );

  // 파이프 (하단)
  final pipeBottom = Sprite(
    id: 'pipe_bottom',
    position: Position(screenWidth, 450),
    size: Size(80, 200),
    backgroundColor: Color(r: 0, g: 150, b: 0),
    eventHandlers: [
      EventHandler(
        type: EventType.update,
        action: ScrollAction(spriteId: 'pipe_bottom', speed: -200),
      ),
    ],
  );

  // 점수 텍스트
  final scoreText = Sprite(
    id: 'score_text',
    position: Position(50, 50),
    size: Size(100, 40),
    backgroundColor: Color(r: 200, g: 200, b: 200),
  );

  final scene = Scene(
    id: 'gameplay',
    title: 'FlappyBird',
    sprites: {
      'player': player,
      'pipe_top': pipeTop,
      'pipe_bottom': pipeBottom,
      'score_text': scoreText,
    },
    backgroundColor: Color(r: 135, g: 206, b: 235), // 하늘색
    globalEvents: [
      // 충돌 감지
      EventHandler(
        type: EventType.update,
        action: CollisionCheckAction(
          spriteId: 'player',
          targetIds: ['pipe_top', 'pipe_bottom'],
          onCollide: GameOverAction(),
        ),
      ),
      // 화면 경계 검사
      EventHandler(
        type: EventType.update,
        action: BoundaryCheckAction(
          spriteId: 'player',
          minY: 0,
          maxY: screenHeight,
          onOutOfBounds: GameOverAction(),
        ),
      ),
      // 파이프 지나감 (점수 증가)
      EventHandler(
        type: EventType.update,
        action: ScoreDetectAction(
          spriteId: 'pipe_top',
          targetX: 100,
        ),
      ),
    ],
  );

  return Game(
    id: 'flappy_bird',
    title: 'FlappyBird',
    screenSize: Size(screenWidth, screenHeight),
    scenes: {'gameplay': scene},
    startSceneId: 'gameplay',
  );
}

