// game_2048.dart - 2048 게임 (난이도: 중)
// 타일을 스와이프해서 같은 숫자끼리 합치는 게임

import '../dsl/game_ast.dart';

// ==================== 2048 게임 정의 ====================

Game createGame2048() {
  const screenWidth = 800.0;
  const screenHeight = 600.0;

  // 4x4 그리드 (각 타일 150x150)
  final tiles = <String, Sprite>{};
  const tileSize = 150.0;
  const gridStart = 25.0;
  const gap = 12.0;

  for (int row = 0; row < 4; row++) {
    for (int col = 0; col < 4; col++) {
      final x = gridStart + (tileSize + gap) * col;
      final y = gridStart + (tileSize + gap) * row;
      tiles['tile_${row}_${col}'] = Sprite(
        id: 'tile_${row}_${col}',
        position: Position(x, y),
        size: Size(tileSize, tileSize),
        backgroundColor: Color(r: 200, g: 200, b: 200), // 기본: 회색
      );
    }
  }

  // 점수 표시
  final scoreDisplay = Sprite(
    id: 'score_display',
    position: Position(650, 50),
    size: Size(140, 60),
    backgroundColor: Color(r: 100, g: 100, b: 100),
  );

  // 목표 (2048 달성) 텍스트
  final goalText = Sprite(
    id: 'goal_text',
    position: Position(650, 130),
    size: Size(140, 60),
    backgroundColor: Color(r: 200, g: 200, b: 0), // 노랑
  );

  final scene = Scene(
    id: 'gameplay',
    title: '2048',
    sprites: {...tiles, 'score_display': scoreDisplay, 'goal_text': goalText},
    backgroundColor: Color(r: 250, g: 248, b: 245), // 베이지
    globalEvents: [
      // 게임 시작: 랜덤 타일 2개 생성
      EventHandler(
        type: EventType.custom,
        action: SpawnRandomTileAction(count: 2),
      ),
      // 스와이프 감지
      EventHandler(
        type: EventType.touch,
        action: SwipeDetectAction(
          onSwipe: TileSlideAction(direction: 'auto'),
        ),
      ),
      // 2048 달성 감지
      EventHandler(
        type: EventType.update,
        action: WinConditionCheckAction(targetValue: 2048),
      ),
    ],
  );

  return Game(
    id: 'game_2048',
    title: '2048',
    screenSize: Size(screenWidth, screenHeight),
    scenes: {'gameplay': scene},
    startSceneId: 'gameplay',
  );
}

