// tap_master.dart - TapMaster 게임 (난이도: 하)
// 나타나는 목표를 빠르게 탭해서 점수를 얻는다

import '../dsl/game_ast.dart';

// ==================== TapMaster 게임 정의 ====================

Game createTapMasterGame() {
  const screenWidth = 800.0;
  const screenHeight = 600.0;

  // 탭 목표 (처음에는 숨김)
  final tapTarget = Sprite(
    id: 'tap_target',
    position: Position(400, 300),
    size: Size(80, 80),
    backgroundColor: Color(r: 100, g: 200, b: 255), // 밝은 파강
    eventHandlers: [
      // 탭 감지
      EventHandler(
        type: EventType.touch,
        action: TargetTappedAction(spriteId: 'tap_target'),
      ),
    ],
  );

  // 타이머 텍스트
  final timerDisplay = Sprite(
    id: 'timer_display',
    position: Position(700, 50),
    size: Size(100, 60),
    backgroundColor: Color(r: 200, g: 100, b: 100),
  );

  // 점수 텍스트
  final scoreDisplay = Sprite(
    id: 'score_display',
    position: Position(100, 50),
    size: Size(100, 60),
    backgroundColor: Color(r: 100, g: 200, b: 100),
  );

  // 목표 획득 수 텍스트
  final targetCountDisplay = Sprite(
    id: 'target_count_display',
    position: Position(400, 50),
    size: Size(100, 60),
    backgroundColor: Color(r: 200, g: 200, b: 100),
  );

  final scene = Scene(
    id: 'gameplay',
    title: 'TapMaster',
