    backgroundColor: Color(r: 240, g: 240, b: 240), // 밝은 회색
    globalEvents: [
      // 게임 시작: 30초 카운트다운
      EventHandler(
        type: EventType.custom,
        action: StartGameTimerAction(duration: 30000), // 30초
