        type: EventType.custom,
        action: MoveTargetRandomAction(
          spriteId: 'tap_target',
          screenWidth: screenWidth,
          screenHeight: screenHeight,
        ),
      ),
    ],
  );

  return Game(
    id: 'tap_master',
    title: 'TapMaster',
    screenSize: Size(screenWidth, screenHeight),
    scenes: {'gameplay': scene},
