// maze.dart - Maze 게임 (난이도: 상)
// 미로를 빠져나가서 목표에 도달하는 게임

import '../dsl/game_ast.dart';

// ==================== Maze 게임 정의 ====================

Game createMazeGame() {
  const screenWidth = 800.0;
  const screenHeight = 600.0;
  const cellSize = 20.0;

  // 플레이어
  final player = Sprite(
    id: 'player',
    position: Position(cellSize * 2, cellSize * 2),
    size: Size(cellSize * 0.8, cellSize * 0.8),
    backgroundColor: Color(r: 0, g: 200, b: 0), // 초록
    eventHandlers: [
      // 화살표/터치로 이동
      EventHandler(
        type: EventType.touch,
        action: MazePlayerMoveAction(spriteId: 'player'),
      ),
    ],
  );

  // 목표 지점
  final goal = Sprite(
    id: 'goal',
    position: Position(
      cellSize * ((screenWidth ~/ cellSize) - 2),
      cellSize * ((screenHeight ~/ cellSize) - 2),
    ),
    size: Size(cellSize * 0.9, cellSize * 0.9),
    backgroundColor: Color(r: 255, g: 200, b: 0), // 황색
  );

  // 미로 벽들 (런타임에 동적 생성)
  // 예시로 몇 개 추가
  final walls = <String, Sprite>{};
  final wallIds = <String>[];

  // 격자 벽 생성 (간단한 미로)
  for (int i = 0; i < (screenWidth ~/ cellSize); i++) {
    for (int j = 0; j < (screenHeight ~/ cellSize); j++) {
      // 미로 패턴 (짝수 위치)
      if ((i % 2 == 0 && j % 2 == 1) || (i % 2 == 1 && j % 2 == 0)) {
        final wallId = 'wall_${i}_${j}';
        walls[wallId] = Sprite(
          id: wallId,
          position: Position(cellSize * i, cellSize * j),
          size: Size(cellSize, cellSize),
          backgroundColor: Color(r: 100, g: 100, b: 100), // 회색
        );
        wallIds.add(wallId);
      }
    }
  }

  final sprites = {
    'player': player,
    'goal': goal,
    ...walls,
  };

  // 시간 제한 텍스트
  final timeDisplay = Sprite(
    id: 'time_display',
    position: Position(700, 50),
    size: Size(100, 60),
    backgroundColor: Color(r: 200, g: 100, b: 100),
  );

  // 난이도 텍스트
  final difficultyDisplay = Sprite(
    id: 'difficulty_display',
    position: Position(100, 50),
    size: Size(100, 60),
    backgroundColor: Color(r: 100, g: 100, b: 200),
  );

  final scene = Scene(
    id: 'gameplay',
    title: 'Maze',
    sprites: sprites,
    backgroundColor: Color(r: 200, g: 200, b: 200), // 밝은 회색
    globalEvents: [
      // 게임 시작: 60초 제한
      EventHandler(
        type: EventType.custom,
        action: StartMazeTimerAction(duration: 60000), // 60초
      ),
      // 타이머 업데이트
      EventHandler(
        type: EventType.update,
        action: UpdateMazeTimerAction(),
      ),
      // 충돌 감지 (벽과)
      EventHandler(
        type: EventType.update,
        action: MazeCollisionCheckAction(
          playerId: 'player',
          wallIds: wallIds,
        ),
      ),
      // 목표 도달 감지
      EventHandler(
        type: EventType.update,
        action: MazeGoalCheckAction(
          playerId: 'player',
          goalId: 'goal',
        ),
      ),
      // 시간 종료 감지
      EventHandler(
        type: EventType.update,
        action: MazeTimeExpiredAction(),
      ),
    ],
  );

  return Game(
    id: 'maze',
    title: 'Maze',
    screenSize: Size(screenWidth, screenHeight),
    scenes: {'gameplay': scene},
    startSceneId: 'gameplay',
  );
}

// ==================== 커스텀 액션들 ====================

class MazePlayerMoveAction extends GameAction {
  final String spriteId;

  MazePlayerMoveAction({required this.spriteId});

  @override
  void execute(GameRuntime runtime) {
    // 터치 또는 화살표 키로 플레이어 이동
    // 상/하/좌/우 4 방향만 가능
    // cellSize만큼 이동
  }
}

class StartMazeTimerAction extends GameAction {
  final int duration;

  StartMazeTimerAction({required this.duration});

  @override
  void execute(GameRuntime runtime) {
    // 미로 게임 타이머 시작
  }
}

class UpdateMazeTimerAction extends GameAction {
  @override
  void execute(GameRuntime runtime) {
    // 매 프레임 타이머 감소
    // 화면에 MM:SS 형식으로 표시
  }
}

class MazeCollisionCheckAction extends GameAction {
  final String playerId;
  final List<String> wallIds;

  MazeCollisionCheckAction({
    required this.playerId,
    required this.wallIds,
  });

  @override
  void execute(GameRuntime runtime) {
    // 플레이어와 모든 벽의 충돌 확인
    // 충돌하면 플레이어 이동 거부
  }
}

class MazeGoalCheckAction extends GameAction {
  final String playerId;
  final String goalId;

  MazeGoalCheckAction({
    required this.playerId,
    required this.goalId,
  });

  @override
  void execute(GameRuntime runtime) {
    // 플레이어와 목표 위치 비교
    // 도달했으면 게임 승리
    // 남은 시간을 점수로 환산
  }
