// game_selector_screen.dart - 게임 선택 화면

import 'package:flutter/material.dart';
import 'package:flame/game.dart';
import '../dsl/game_parser.dart';
import '../services/flame_game_runtime.dart';
import '../main.dart';

class GameSelectorScreen extends StatefulWidget {
  const GameSelectorScreen({Key? key}) : super(key: key);

  @override
  State<GameSelectorScreen> createState() => _GameSelectorScreenState();
}

class _GameSelectorScreenState extends State<GameSelectorScreen> {
  final List<({String name, String dsl, String description})> _games = [
    (
      name: 'Simple Game',
      description: '터치로 플레이어를 움직여 골에 도달하세요',
      dsl: SampleGames.simpleGame
    ),
    (
      name: 'Bounce Game',
      description: '공을 반사판으로 튀겨보세요',
      dsl: SampleGames.bounceGame
    ),
    (
      name: 'Runner Game',
      description: '계속 달리며 장애물을 피하세요',
      dsl: SampleGames.runnerGame
    ),
  ];

  @override
  Widget build(BuildContext context) {
    return ListView.builder(
      padding: const EdgeInsets.all(16),
      itemCount: _games.length,
      itemBuilder: (context, index) {
        final game = _games[index];
        return Card(
          margin: const EdgeInsets.only(bottom: 12),
          child: ListTile(
            leading: const Icon(Icons.videogame_asset),
            title: Text(game.name),
            subtitle: Text(game.description),
            trailing: const Icon(Icons.arrow_forward_ios),
            onTap: () => _playGame(game.dsl),
          ),
        );
      },
    );
  }

  Future<void> _playGame(String dsl) async {
    try {
