// game_selector_screen.dart - 게임 선택 화면

import 'package:flutter/material.dart';
import 'package:flame/game.dart';
import '../engine/flame_game_runtime.dart';
import '../games/flappy_bird.dart';
import '../games/game_2048.dart';
import '../games/pong.dart';
import '../games/tap_master.dart';
import '../games/maze.dart';

class GameInfo {
  final String id;
  final String name;
  final String description;
  final String difficulty; // 하, 중, 상
  final IconData icon;
  final Function() createGame;

  GameInfo({
    required this.id,
    required this.name,
    required this.description,
    required this.difficulty,
    required this.icon,
    required this.createGame,
  });
}

class GameSelectorScreen extends StatefulWidget {
  const GameSelectorScreen({Key? key}) : super(key: key);

  @override
  State<GameSelectorScreen> createState() => _GameSelectorScreenState();
}

class _GameSelectorScreenState extends State<GameSelectorScreen> {
  late final List<GameInfo> _games = [
    GameInfo(
      id: 'flappy_bird',
      name: 'FlappyBird',
      description: '파이프를 피해서 최대한 멀리 날아가세요',
      difficulty: '하',
      icon: Icons.airplanemode_active,
      createGame: createFlappyBirdGame,
    ),
    GameInfo(
      id: 'game_2048',
      name: '2048',
      description: '타일을 스와이프해서 같은 숫자끼리 합치세요',
      difficulty: '중',
      icon: Icons.grid_3x3,
      createGame: createGame2048,
    ),
    GameInfo(
      id: 'pong',
      name: 'Pong',
      description: '패들로 공을 주고받아 점수를 얻으세요',
      difficulty: '중',
      icon: Icons.sports_tennis,
      createGame: createPongGame,
    ),
    GameInfo(
      id: 'tap_master',
      name: 'TapMaster',
      description: '나타나는 목표를 빠르게 탭해서 점수를 올리세요',
      difficulty: '하',
      icon: Icons.touch_app,
      createGame: createTapMasterGame,
    ),
    GameInfo(
      id: 'maze',
      name: 'Maze',
      description: '미로를 빠져나가 목표에 도달하세요',
      difficulty: '상',
      icon: Icons.blender_icon,
      createGame: createMazeGame,
    ),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('게임 선택'),
        elevation: 0,
      ),
      body: ListView.builder(
        padding: const EdgeInsets.all(12),
        itemCount: _games.length,
        itemBuilder: (context, index) {
          final gameInfo = _games[index];
          return GameCard(
            gameInfo: gameInfo,
            onTap: () => _playGame(gameInfo),
          );
        },
      ),
    );
  }

  Future<void> _playGame(GameInfo gameInfo) async {
    try {
      // 게임 AST 생성
      final gameAST = gameInfo.createGame();

      // 게임 런타임 생성
      final gameRuntime = FlameGameRuntime(
        gameAST: gameAST,
        onScoreChanged: (score) {
          print('Score: $score');
        },
        onGameOver: () {
          print('Game Over!');
        },
        onGameWin: () {
          print('You Won!');
        },
      );

      // 게임 화면으로 이동
      if (!mounted) return;

      Navigator.push(
        context,
        MaterialPageRoute(
          builder: (context) => GamePlayScreen(
            game: gameRuntime,
            gameName: gameInfo.name,
          ),
        ),
      );
    } catch (e) {
      _showError('게임 로드 실패: $e');
    }
  }

  void _showError(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: Colors.red,
      ),
    );
  }
}

class GamePlayScreen extends StatefulWidget {
  final FreeLangGameRuntime game;

  const GamePlayScreen({
    Key? key,
    required this.game,
  }) : super(key: key);

  @override
  State<GamePlayScreen> createState() => _GamePlayScreenState();
}

class _GamePlayScreenState extends State<GamePlayScreen> {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('게임 중'),
        leading: IconButton(
          icon: const Icon(Icons.close),
          onPressed: () => Navigator.pop(context),
        ),
      ),
      body: GameWidget(game: widget.game),
    );
  }
}

