// lsp_features.dart - LSP 기반 고급 기능
// 자동 완성, 린터, 코드 포맷팅

// ==================== 자동 완성 ====================

class CompletionItem {
  final String label;
  final String detail;
  final String documentation;
  final String insertText;
  final CompletionItemKind kind;

  CompletionItem({
    required this.label,
    required this.detail,
    required this.documentation,
    required this.insertText,
    required this.kind,
  });
}

enum CompletionItemKind {
  keyword,
  function,
  variable,
  type,
  module,
  snippet,
}

class AutocompleteProvider {
  static const List<String> keywords = [
    'let',
    'if',
    'else',
    'for',
    'while',
    'fn',
    'return',
    'break',
    'continue',
    'match',
    'true',
    'false',
    'nil',
  ];

  static const List<String> builtinFunctions = [
    'print',
    'println',
    'len',
    'push',
    'pop',
    'append',
    'slice',
    'contains',
    'indexOf',
    'toLowerCase',
    'toUpperCase',
    'trim',
    'split',
    'join',
  ];

  static const List<String> builtinTypes = [
    'i32',
    'i64',
    'f32',
    'f64',
    'string',
    'bool',
    'array',
    'object',
  ];

  /// 현재 커서 위치에서 자동 완성 제안 조회
  static List<CompletionItem> getCompletions(
    String code,
    int position,
  ) {
    final completions = <CompletionItem>[];

    // 커서 앞 텍스트 추출
    final beforeCursor = code.substring(0, position);
    final lastWord = _extractLastWord(beforeCursor);

    // 키워드 제안
    for (final keyword in keywords) {
      if (keyword.startsWith(lastWord)) {
        completions.add(CompletionItem(
          label: keyword,
          detail: 'Keyword',
          documentation: 'FreeLang keyword: $keyword',
          insertText: keyword,
          kind: CompletionItemKind.keyword,
        ));
      }
    }

    // 함수 제안
    for (final func in builtinFunctions) {
      if (func.startsWith(lastWord)) {
        completions.add(CompletionItem(
          label: func,
          detail: 'Function',
          documentation: 'Built-in function: $func()',
          insertText: '$func(\${1})',
          kind: CompletionItemKind.function,
        ));
      }
    }

    // 타입 제안
    for (final type in builtinTypes) {
      if (type.startsWith(lastWord)) {
        completions.add(CompletionItem(
          label: type,
          detail: 'Type',
          documentation: 'FreeLang type: $type',
          insertText: type,
          kind: CompletionItemKind.type,
        ));
      }
    }

    // 스니펫 제안
    final snippets = _getSnippets();
    for (final snippet in snippets) {
      if (snippet.label.startsWith(lastWord)) {
        completions.add(snippet);
      }
    }

    return completions;
  }

  static String _extractLastWord(String text) {
    final match = RegExp(r'\w*$').firstMatch(text);
    return match?.group(0) ?? '';
  }

  static List<CompletionItem> _getSnippets() {
    return [
      CompletionItem(
        label: 'fn',
        detail: 'Snippet',
        documentation: 'Function declaration',
        insertText: 'fn \${1:name}(\${2:params}) { \${3} }',
        kind: CompletionItemKind.snippet,
      ),
      CompletionItem(
        label: 'if',
        detail: 'Snippet',
        documentation: 'If statement',
        insertText: 'if (\${1:condition}) { \${2} }',
        kind: CompletionItemKind.snippet,
      ),
      CompletionItem(
        label: 'for',
        detail: 'Snippet',
        documentation: 'For loop',
        insertText: 'for (let i = 0; i < \${1:length}; i++) { \${2} }',
        kind: CompletionItemKind.snippet,
      ),
      CompletionItem(
        label: 'while',
        detail: 'Snippet',
        documentation: 'While loop',
        insertText: 'while (\${1:condition}) { \${2} }',
        kind: CompletionItemKind.snippet,
      ),
    ];
  }
}

// ==================== 린터 ====================

class Diagnostic {
  final int line;
  final int column;
  final String message;
  final DiagnosticSeverity severity;
  final String code;

  Diagnostic({
    required this.line,
    required this.column,
    required this.message,
    required this.severity,
    required this.code,
  });
}

enum DiagnosticSeverity {
  error,
  warning,
  information,
  hint,
}

class Linter {
  /// 코드 린팅 및 문제점 감지
  static List<Diagnostic> lint(String code) {
    final diagnostics = <Diagnostic>[];
    final lines = code.split('\n');

    for (int lineNum = 0; lineNum < lines.length; lineNum++) {
      final line = lines[lineNum];

      // 1. 구문 오류 감지
      final syntaxErrors = _checkSyntaxErrors(line, lineNum);
      diagnostics.addAll(syntaxErrors);

      // 2. 미사용 변수 감지
      final unusedVars = _checkUnusedVariables(code, lineNum);
      diagnostics.addAll(unusedVars);

      // 3. 타입 불일치 감지
      final typeErrors = _checkTypeErrors(line, lineNum);
      diagnostics.addAll(typeErrors);

      // 4. 스타일 경고 감지
      final styleWarnings = _checkStyleWarnings(line, lineNum);
      diagnostics.addAll(styleWarnings);
    }

    return diagnostics;
  }

  static List<Diagnostic> _checkSyntaxErrors(String line, int lineNum) {
    final diagnostics = <Diagnostic>[];

    // 괄호 짝맞음 확인
    int openParen = 0, openBrace = 0, openBracket = 0;
    for (int i = 0; i < line.length; i++) {
      final char = line[i];
      if (char == '(') openParen++;
      else if (char == ')') openParen--;
      else if (char == '{') openBrace++;
      else if (char == '}') openBrace--;
      else if (char == '[') openBracket++;
      else if (char == ']') openBracket--;

      if (openParen < 0 || openBrace < 0 || openBracket < 0) {
        diagnostics.add(Diagnostic(
          line: lineNum,
          column: i,
          message: 'Mismatched closing bracket',
          severity: DiagnosticSeverity.error,
          code: 'syntax-error',
        ));
        break;
      }
    }

    // 문장 끝 세미콜론 확인 (선택사항이지만 권장)
    if (line.trim().isNotEmpty &&
        !line.trim().endsWith('{') &&
        !line.trim().endsWith('}') &&
        !line.trim().endsWith(';')) {
      // 세미콜론 없음 경고 (힌트)
    }

    return diagnostics;
  }

  static List<Diagnostic> _checkUnusedVariables(String code, int lineNum) {
    final diagnostics = <Diagnostic>[];

    // 간단한 패턴 매칭: let x = ... 근데 x를 사용하지 않음
    final letPattern = RegExp(r'let\s+(\w+)\s*=');
    final lines = code.split('\n');

    for (int i = 0; i < lines.length; i++) {
      final match = letPattern.firstMatch(lines[i]);
      if (match != null) {
        final varName = match.group(1)!;
        // 이후 줄에서 varName이 사용되는지 확인
        bool isUsed = false;
        for (int j = i + 1; j < lines.length; j++) {
          if (lines[j].contains(varName)) {
            isUsed = true;
            break;
          }
        }

        if (!isUsed && i == lineNum) {
          diagnostics.add(Diagnostic(
            line: i,
            column: match.start,
            message: "Variable '$varName' is defined but never used",
            severity: DiagnosticSeverity.warning,
            code: 'unused-variable',
          ));
        }
      }
    }

    return diagnostics;
  }

  static List<Diagnostic> _checkTypeErrors(String line, int lineNum) {
    final diagnostics = <Diagnostic>[];

    // 간단한 타입 체크: string + number 같은 명백한 오류
    if (line.contains('+') && line.contains('"')) {
