// snippet_uploader.dart - 스니펫 업로더
// IDE에서 작성한 코드를 Hub에 업로드

import 'package:dio/dio.dart';

class SnippetUploadResponse {
  final bool success;
  final String snippetId;
  final String shareUrl;

  SnippetUploadResponse({
    required this.success,
    required this.snippetId,
    required this.shareUrl,
  });

  factory SnippetUploadResponse.fromJson(Map<String, dynamic> json) {
    return SnippetUploadResponse(
      success: json['success'] as bool? ?? false,
      snippetId: json['data']?['id'] as String? ?? '',
      shareUrl: 'hub://snippet/${json['data']?['id'] ?? ''}',
    );
  }
}

class SnippetUploader {
  static const String _baseUrl = 'http://localhost:3000/api/v2';
  late Dio _dio;
  bool _initialized = false;

  SnippetUploader();

  Future<void> initialize() async {
    if (_initialized) return;

    _dio = Dio(
      BaseOptions(
        baseUrl: _baseUrl,
        connectTimeout: const Duration(seconds: 10),
        receiveTimeout: const Duration(seconds: 10),
        contentType: 'application/json',
      ),
    );

    _initialized = true;
  }

  /// Hub에 스니펫 업로드
  /// 성공 시 공유 링크 반환
  Future<SnippetUploadResponse> uploadSnippet({
    required String code,
    required String title,
    required List<String> tags,
    String? description,
  }) async {
    try {
      await initialize();

      final response = await _dio.post<Map<String, dynamic>>(
        '/snippets',
        data: {
          'title': title,
          'code': code,
          'tags': tags,
          'description': description ?? '',
        },
      );

      if (response.statusCode == 200 || response.statusCode == 201) {
        return SnippetUploadResponse.fromJson(response.data ?? {});
      } else {
        throw Exception('Upload failed: ${response.statusCode}');
      }
    } on DioException catch (e) {
      throw Exception('Upload error: ${e.message}');
    }
  }

  /// 현재 코드의 추천 태그 생성
  List<String> suggestTags(String code) {
    final tags = <String>{};

    // 키워드 기반 태그 추천
    if (code.contains('for ') || code.contains('while ')) {
      tags.add('loop');
    }
    if (code.contains('fn ')) {
      tags.add('function');
    }
    if (code.contains('array') || code.contains('[')) {
      tags.add('array');
    }
    if (code.contains('string') || code.contains('"')) {
      tags.add('string');
    }
    if (code.contains('if ') || code.contains('else')) {
      tags.add('conditional');
    }
    if (code.contains('match ')) {
      tags.add('pattern-matching');
    }
    if (code.contains('//')) {
      tags.add('commented');
    }

    // 코드 길이 기반 태그
    if (code.length < 100) {
      tags.add('snippet');
    } else if (code.length < 500) {
      tags.add('utility');
    } else {
      tags.add('algorithm');
    }

    return tags.toList();
  }

  /// 제목 자동 생성 (코드의 첫 줄에서)
  String suggestTitle(String code) {
    final lines = code.split('\n');
    for (final line in lines) {
      final trimmed = line.trim();
      if (trimmed.isNotEmpty && !trimmed.startsWith('//')) {
        // 첫 번째 의미있는 줄에서 제목 추출
        if (trimmed.startsWith('fn ')) {
          final match = RegExp(r'fn\s+(\w+)').firstMatch(trimmed);
          return 'Function: ${match?.group(1) ?? 'unnamed'}';
        }
        return trimmed.length > 50
            ? '${trimmed.substring(0, 47)}...'
            : trimmed;
      }
    }
    return 'Untitled Snippet';
  }
}

