      if (response.statusCode == 200 || response.statusCode == 201) {
        return SnippetUploadResponse.fromJson(response.data ?? {});
      } else {
        throw Exception('Upload failed: ${response.statusCode}');
      }
    } on DioException catch (e) {
      throw Exception('Upload error: ${e.message}');
    }
  }

  /// 현재 코드의 추천 태그 생성
  List<String> suggestTags(String code) {
    final tags = <String>{};

    // 키워드 기반 태그 추천
    if (code.contains('for ') || code.contains('while ')) {
      tags.add('loop');
    }
    if (code.contains('fn ')) {
      tags.add('function');
    }
    if (code.contains('array') || code.contains('[')) {
      tags.add('array');
    }
    if (code.contains('string') || code.contains('"')) {
      tags.add('string');
    }
    if (code.contains('if ') || code.contains('else')) {
      tags.add('conditional');
    }
    if (code.contains('match ')) {
      tags.add('pattern-matching');
    }
    if (code.contains('//')) {
      tags.add('commented');
    }

    // 코드 길이 기반 태그
    if (code.length < 100) {
      tags.add('snippet');
    } else if (code.length < 500) {
      tags.add('utility');
    } else {
      tags.add('algorithm');
    }

    return tags.toList();
  }

  /// 제목 자동 생성 (코드의 첫 줄에서)
  String suggestTitle(String code) {
    final lines = code.split('\n');
    for (final line in lines) {
      final trimmed = line.trim();
      if (trimmed.isNotEmpty && !trimmed.startsWith('//')) {
        // 첫 번째 의미있는 줄에서 제목 추출
        if (trimmed.startsWith('fn ')) {
          final match = RegExp(r'fn\s+(\w+)').firstMatch(trimmed);
          return 'Function: ${match?.group(1) ?? 'unnamed'}';
        }
        return trimmed.length > 50
            ? '${trimmed.substring(0, 47)}...'
            : trimmed;
      }
    }
    return 'Untitled Snippet';
  }
}

