import 'package:flutter/material.dart';
import '../services/lsp_features.dart';

class AutocompletePopup extends StatefulWidget {
  final String code;
  final int position;
  final Function(String) onSelected;
  final Offset position_offset;

  const AutocompletePopup({
    Key? key,
    required this.code,
    required this.position,
    required this.onSelected,
    required this.position_offset,
  }) : super(key: key);

  @override
  State<AutocompletePopup> createState() => _AutocompletePopupState();
}

class _AutocompletePopupState extends State<AutocompletePopup> {
  late List<CompletionItem> suggestions;
  int selectedIndex = 0;

  @override
  void initState() {
    super.initState();
    suggestions = AutocompleteProvider.getCompletions(widget.code, widget.position);
  }

  @override
  Widget build(BuildContext context) {
    if (suggestions.isEmpty) {
      return const SizedBox.shrink();
    }

    return Positioned(
      left: widget.position_offset.dx,
      top: widget.position_offset.dy,
      child: Material(
        elevation: 8,
        borderRadius: BorderRadius.circular(4),
        child: Container(
          width: 300,
          constraints: const BoxConstraints(maxHeight: 300),
          decoration: BoxDecoration(
            color: Colors.grey[900],
            borderRadius: BorderRadius.circular(4),
            border: Border.all(color: Colors.grey[700]!),
          ),
          child: ListView.builder(
            padding: EdgeInsets.zero,
            itemCount: suggestions.length,
            itemBuilder: (context, index) {
              final item = suggestions[index];
              return CompletionItemWidget(
                item: item,
                isSelected: index == selectedIndex,
                onTap: () => widget.onSelected(item.insertText),
              );
            },
          ),
        ),
      ),
    );
  }
}

class CompletionItemWidget extends StatelessWidget {
  final CompletionItem item;
  final bool isSelected;
  final VoidCallback onTap;

  const CompletionItemWidget({
    Key? key,
    required this.item,
    required this.isSelected,
    required this.onTap,
  }) : super(key: key);

  IconData _getKindIcon(CompletionItemKind kind) {
    switch (kind) {
      case CompletionItemKind.keyword:
        return Icons.label;
      case CompletionItemKind.function:
        return Icons.functions;
      case CompletionItemKind.variable:
        return Icons.checklist;
      case CompletionItemKind.type:
        return Icons.category;
      case CompletionItemKind.module:
        return Icons.library_books;
      case CompletionItemKind.snippet:
        return Icons.code;
    }
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        color: isSelected ? Colors.teal[700] : Colors.transparent,
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
        child: Row(
          children: [
            Icon(
              _getKindIcon(item.kind),
              size: 16,
              color: Colors.teal,
            ),
            const SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    item.label,
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.bold,
                      color: Colors.white,
                    ),
                  ),
                  Text(
                    item.detail,
                    style: TextStyle(
                      fontSize: 10,
                      color: Colors.grey[500],
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

