// lint_panel.dart - 린트 에러 패널

import 'package:flutter/material.dart';
import '../services/lsp_features.dart';

class LintPanel extends StatefulWidget {
  final String code;

  const LintPanel({
    Key? key,
    required this.code,
  }) : super(key: key);

  @override
  State<LintPanel> createState() => _LintPanelState();
}

class _LintPanelState extends State<LintPanel> {
  late List<Diagnostic> diagnostics;
  bool _isExpanded = false;

  @override
  void initState() {
    super.initState();
    diagnostics = Linter.lint(widget.code);
  }

  @override
  void didUpdateWidget(LintPanel oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.code != widget.code) {
      diagnostics = Linter.lint(widget.code);
    }
  }

  Color _getSeverityColor(DiagnosticSeverity severity) {
    switch (severity) {
      case DiagnosticSeverity.error:
        return Colors.red;
      case DiagnosticSeverity.warning:
        return Colors.orange;
      case DiagnosticSeverity.information:
        return Colors.blue;
      case DiagnosticSeverity.hint:
        return Colors.grey;
    }
  }

  IconData _getSeverityIcon(DiagnosticSeverity severity) {
    switch (severity) {
      case DiagnosticSeverity.error:
        return Icons.error;
      case DiagnosticSeverity.warning:
        return Icons.warning;
      case DiagnosticSeverity.information:
        return Icons.info;
      case DiagnosticSeverity.hint:
        return Icons.lightbulb;
    }
  }

  String _getSeverityLabel(DiagnosticSeverity severity) {
    switch (severity) {
      case DiagnosticSeverity.error:
        return 'Error';
      case DiagnosticSeverity.warning:
        return 'Warning';
      case DiagnosticSeverity.information:
        return 'Information';
      case DiagnosticSeverity.hint:
        return 'Hint';
    }
  }

  @override
  Widget build(BuildContext context) {
    final errorCount = diagnostics.where((d) => d.severity == DiagnosticSeverity.error).length;
    final warningCount = diagnostics.where((d) => d.severity == DiagnosticSeverity.warning).length;

    return Container(
      color: Colors.grey[900],
      child: Column(
        children: [
          // 패널 헤더
          GestureDetector(
            onTap: () => setState(() => _isExpanded = !_isExpanded),
            child: Container(
              color: Colors.grey[850],
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
              child: Row(
                children: [
                  Icon(
                    _isExpanded ? Icons.expand_less : Icons.expand_more,
                    size: 20,
                    color: Colors.grey[400],
                  ),
                  const SizedBox(width: 8),
                  if (errorCount > 0)
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                      decoration: BoxDecoration(
                        color: Colors.red.withOpacity(0.2),
                        borderRadius: BorderRadius.circular(3),
                      ),
                      child: Text(
                        'Errors: $errorCount',
                        style: const TextStyle(
                          fontSize: 11,
                          color: Colors.red,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ),
                  const SizedBox(width: 8),
                  if (warningCount > 0)
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                      decoration: BoxDecoration(
                        color: Colors.orange.withOpacity(0.2),
                        borderRadius: BorderRadius.circular(3),
                      ),
                      child: Text(
                        'Warnings: $warningCount',
                        style: const TextStyle(
                          fontSize: 11,
                          color: Colors.orange,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ),
                  if (errorCount == 0 && warningCount == 0)
                    Text(
                      'No issues',
                      style: TextStyle(
                        fontSize: 11,
                        color: Colors.green[400],
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  const Spacer(),
                  Text(
                    '${diagnostics.length} issues',
                    style: TextStyle(
                      fontSize: 11,
                      color: Colors.grey[500],
                    ),
                  ),
                ],
              ),
            ),
          ),

          // 펼쳐진 내용
          if (_isExpanded)
            Expanded(
              child: diagnostics.isEmpty
                  ? Center(
                      child: Text(
                        'No linting issues',
                        style: TextStyle(
                          color: Colors.grey[500],
                          fontSize: 12,
                        ),
                      ),
                    )
                  : ListView.builder(
                      padding: const EdgeInsets.all(8),
                      itemCount: diagnostics.length,
                      itemBuilder: (context, index) {
                        final diag = diagnostics[index];
                        return Container(
                          margin: const EdgeInsets.only(bottom: 6),
                          padding: const EdgeInsets.all(8),
                          decoration: BoxDecoration(
                            color: _getSeverityColor(diag.severity).withOpacity(0.1),
                            border: Border.all(
                              color: _getSeverityColor(diag.severity).withOpacity(0.3),
                            ),
                            borderRadius: BorderRadius.circular(4),
                          ),
                          child: Row(
                            children: [
                              Icon(
                                _getSeverityIcon(diag.severity),
                                size: 16,
                                color: _getSeverityColor(diag.severity),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Row(
                                      children: [
                                        Text(
                                          _getSeverityLabel(diag.severity),
                                          style: TextStyle(
                                            fontSize: 10,
                                            color: _getSeverityColor(diag.severity),
                                            fontWeight: FontWeight.bold,
                                          ),
                                        ),
                                        const SizedBox(width: 8),
                                        Text(
                                          'Line ${diag.line + 1}:${diag.column}',
                                          style: TextStyle(
                                            fontSize: 10,
                                            color: Colors.grey[500],
                                          ),
                                        ),
                                      ],
                                    ),
                                    const SizedBox(height: 2),
                                    Text(
                                      diag.message,
                                      style: const TextStyle(
                                        fontSize: 11,
                                        color: Colors.white,
                                      ),
                                      maxLines: 2,
                                      overflow: TextOverflow.ellipsis,
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        );
                      },
                    ),
            ),
        ],
      ),
    );
  }
}

