    // 에디터 내용을 현재 파일로 업데이트
    await _getEditorContent();

    if (_currentFile != null && _currentFile!.content.isNotEmpty) {
      // 오류 확인
      if (_errorCount > 0) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('⚠️ 오류가 있습니다. 수정 후 실행하세요'),
