          content: Text('저장되었습니다'),
          duration: Duration(seconds: 1),
        ),
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('저장 실패: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  void _newFile() {
    setState(() {
      _currentFile = CodeFile(
        name: 'new_file_${DateTime.now().millisecondsSinceEpoch}.fl',
        content: '',
      );
      _isModified = false;
    });
  }

  Future<void> _openFile() async {
    if (!mounted) return;

    final selectedFile = await Navigator.push<CodeFile>(
      context,
      MaterialPageRoute(
        builder: (_) => FilesScreen(fileManager: widget.fileManager),
      ),
    );

    if (selectedFile != null && mounted) {
      try {
        final content = await widget.fileManager.readFile(selectedFile.path!);
        setState(() {
          _currentFile = CodeFile(
            name: selectedFile.name,
            content: content,
            path: selectedFile.path,
          );
          _isModified = false;
        });
        _initializeEditor();
      } catch (e) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('파일 로드 실패: $e')),
        );
      }
    }
  }
}

