// lsp_features_test.dart - LSP 기능 테스트

import 'package:flutter_test/flutter_test.dart';
import 'package:ide/services/lsp_features.dart';

void main() {
  group('AutocompleteProvider', () {
    test('자동 완성: 키워드 제안', () {
      const code = 'le';
      const position = 2;

      final completions = AutocompleteProvider.getCompletions(code, position);

      expect(completions.isNotEmpty, true);
      expect(
        completions.any((item) => item.label == 'let'),
        true,
      );
    });

    test('자동 완성: 함수 제안', () {
      const code = 'print';
      const position = 5;

      final completions = AutocompleteProvider.getCompletions(code, position);

      expect(
        completions.any((item) => item.label == 'print'),
        true,
      );
    });

    test('자동 완성: 타입 제안', () {
      const code = 'i3';
      const position = 2;

      final completions = AutocompleteProvider.getCompletions(code, position);

      expect(
        completions.any((item) => item.label == 'i32'),
        true,
      );
    });

    test('자동 완성: 스니펫 제안', () {
      const code = 'fn';
      const position = 2;

      final completions = AutocompleteProvider.getCompletions(code, position);

      expect(
        completions.any((item) => item.kind == CompletionItemKind.snippet),
        true,
      );
    });
  });

  group('Linter', () {
    test('린팅: 구문 오류 감지', () {
