print used
''';

      final diagnostics = Linter.lint(code);

      expect(
        diagnostics.any((d) => d.code == 'unused-variable'),
        true,
      );
    });

    test('린팅: 들여쓰기 경고', () {
      const code = 'let x = 1\n   if x { print x }'; // 3칸 들여쓰기

