    let x = 1
        if x { print x }
}''';

      final formatted = CodeFormatter.format(code);

      expect(formatted.contains('  let'), true);
      expect(formatted.contains('    if'), true);
    });

    test('포맷팅: 공백 정리', () {
      const code = 'let x = 1  \nlet y = 2   ';

      final formatted = CodeFormatter.format(code);

      expect(!formatted.contains('  \n'), true);
    });

    test('포맷팅: 연산자 공백', () {
      const code = 'let x=1+2';

      final formatted = CodeFormatter.format(code);

      expect(formatted.contains(' = '), true);
      expect(formatted.contains(' + '), true);
    });

    test('포맷팅: 파일 끝 개행', () {
      const code = 'let x = 1';

      final formatted = CodeFormatter.format(code);

      expect(formatted.endsWith('\n'), true);
    });

    test('포맷팅: 완전한 코드', () {
      const code = '''fn fib(n) {
if n<=1 { n }
else { fib(n-1)+fib(n-2) }
}''';

      final formatted = CodeFormatter.format(code);

      // 정규화되어야 함
      expect(formatted.contains('  if'), true);
      expect(formatted.contains('  else'), true);
      expect(formatted.contains('fn fib'), true);
    });
  });
}

